package org.ssssssss.magicapi.iot.bus;
import com.fasterxml.jackson.databind.ObjectMapper; import org.apache.rocketmq.spring.core.RocketMQTemplate; import org.springframework.boot.autoconfigure.AutoConfiguration; import org.springframework.boot.autoconfigure.condition.*; import org.springframework.context.annotation.Bean; import org.ssssssss.magicapi.iot.core.spi.DeviceMessageBus;
@AutoConfiguration @ConditionalOnProperty(prefix="iot.providers.message-bus",name="type",havingValue="rocketmq") @ConditionalOnBean(RocketMQTemplate.class) public class RocketMqMessageBusAutoConfiguration { @Bean @ConditionalOnMissingBean(DeviceMessageBus.class) DeviceMessageBus deviceMessageBus(RocketMQTemplate template,ObjectMapper mapper,org.springframework.core.env.Environment env){return new RocketMqDeviceMessageBus(template,mapper,env.getProperty("iot.providers.message-bus.name-server",env.getProperty("rocketmq.name-server","127.0.0.1:9876")),env.getProperty("iot.providers.message-bus.topic","iot-device-messages"),env.getProperty("iot.providers.message-bus.retries",Integer.class,3));} }
